/** Independent theme axes (one per multi-mode variable collection) and their modes. */
export const themeAxes = { Colors: ["Light", "Dark"] } as const;

export type ThemeAxis = keyof typeof themeAxes;

export type ThemeSelection = {
  [A in ThemeAxis]?: (typeof themeAxes)[A][number];
};

export const defaultThemeSelection = {
  Colors: "Light",
} as const satisfies ThemeSelection;

type Widen<T> = T extends string
  ? string
  : T extends number
    ? number
    : T extends boolean
      ? boolean
      : { -readonly [K in keyof T]: Widen<T[K]> };

/** Widened so every mode's values (not just the default's literals) fit it. */
export type Theme = Widen<typeof base & (typeof modes)["Colors"]["Light"]>;

type Tree = Record<string, unknown>;

function merge(target: Tree, source: Tree): Tree {
  for (const [key, value] of Object.entries(source)) {
    const existing = target[key];
    target[key] =
      typeof value === "object" && value !== null
        ? merge(
            typeof existing === "object" && existing !== null
              ? { ...(existing as Tree) }
              : {},
            value as Tree,
          )
        : value;
  }
  return target;
}

const cache = new Map<string, Theme>();

/** The theme for one mode per axis; an unspecified axis uses its default mode. */
export function resolveTheme(selection: ThemeSelection = {}): Theme {
  const axes = Object.keys(themeAxes) as ThemeAxis[];
  const picked = axes.map(
    (axis) => selection[axis] ?? defaultThemeSelection[axis],
  );
  const key = JSON.stringify(picked);
  let theme = cache.get(key);
  if (!theme) {
    let merged: Tree = merge({}, base);
    axes.forEach((axis, i) => {
      const partials = modes[axis] as unknown as Record<string, Tree>;
      merged = merge(merged, partials[picked[i] as string]);
    });
    theme = merged as unknown as Theme;
    cache.set(key, theme);
  }
  return theme;
}

export const theme = resolveTheme();
